(7412282, 1168563, 124815, '<td valign="top">Very good stop movement, just the way we played as kids. Good cityscape. The sepia is less appropriate for the city of concrete and steel in my opinion</td>', 'Very good stop movement, just the way we played as kids. Good cityscape. The sepia is less appropriate for the city of concrete and steel in my opinion', '2015-10-26 08:30:07.000000', NULL, 1),
(7412283, 1168581, 124815, '<td valign="top">They look edible! A beautiful image with an excellent processing</td>', 'They look edible! A beautiful image with an excellent processing', '2015-10-26 08:31:58.000000', NULL, 1),
