(7412390, 1168291, 23484, '<td valign="top">Very nicely done.  I need to get out to that part of the state again.</td>', 'Very nicely done.  I need to get out to that part of the state again.', '2015-10-26 16:29:18.000000', NULL, 1),
(7412391, 1168389, 23484, '<td valign="top">The perspective makes such great leading lines.</td>', 'The perspective makes such great leading lines.', '2015-10-26 16:29:51.000000', NULL, 1),
(7412425, 1168566, 100831, '<td valign="top">A wonderful cow image</td>', 'A wonderful cow image', '2015-10-26 21:59:47.000000', NULL, 1),
(7412430, 1168539, 112739, '<td valign="top">Maybe a nit pick, but I would vote this a 10 if the dust spots were removed. Other than that extremely small nit, this is a glorious interpretation of a landscape being overtaken and enveloped by a sea that has one mission, to leave no trace whatsoever. It''s good to see the land holding it''s ground, for now.</td>', 'Maybe a nit pick, but I would vote this a 10 if the dust spots were removed. Other than that extremely small nit, this is a glorious interpretation of a landscape being overtaken and enveloped by a sea that has one mission, to leave no trace whatsoever. It''s good to see the land holding it''s ground, for now.', '2015-10-26 22:20:27.000000', NULL, 1),
(7412431, 1168530, 112739, '<td valign="top">Nice wide open view. A little too contrasty for my tastes, but all in all, a great image. Nice light on the vertical cliffs and hills.</td>', 'Nice wide open view. A little too contrasty for my tastes, but all in all, a great image. Nice light on the vertical cliffs and hills.', '2015-10-26 22:21:46.000000', NULL, 1),
(7412432, 1168577, 114225, '<td valign="top">Yes, this is a wall shot.</td>', 'Yes, this is a wall shot.', '2015-10-26 22:22:45.000000', NULL, 1),
(7412433, 1168569, 112739, '<td valign="top">Very well done seascape. The dark balance well with the rest of the image and the eye can travel easily without any overbright areas.</td>', 'Very well done seascape. The dark balance well with the rest of the image and the eye can travel easily without any overbright areas.', '2015-10-26 22:22:52.000000', NULL, 1),
(7412434, 1168582, 114225, '<td valign="top">Damn, that is insane light.</td>', 'Damn, that is insane light.', '2015-10-26 22:22:56.000000', NULL, 1),
(7412435, 1168594, 112739, '<td valign="top">Love the movement. Love the light on the rocks, love the sunset light. The green sky is a little off to me though. But, it does seem to work within the confines of the image.</td>', 'Love the movement. Love the light on the rocks, love the sunset light. The green sky is a little off to me though. But, it does seem to work within the confines of the image.', '2015-10-26 22:24:51.000000', NULL, 1),
(7412436, 1168548, 112739, '<td valign="top">Great use of a wide angle lens.</td>', 'Great use of a wide angle lens.', '2015-10-26 22:25:16.000000', NULL, 1),
(7412437, 1168610, 112739, '<td valign="top">Nice autumn colors.</td>', 'Nice autumn colors.', '2015-10-26 22:27:49.000000', NULL, 1),
(7412438, 1168613, 112739, '<td valign="top">The water splashes really bring a lot of life to the image.</td>', 'The water splashes really bring a lot of life to the image.', '2015-10-26 22:28:32.000000', NULL, 1),
(7412439, 1168601, 112739, '<td valign="top">The calm water really has nice reflective qualities.</td>', 'The calm water really has nice reflective qualities.', '2015-10-26 22:30:42.000000', NULL, 1),
(7412440, 1168632, 114225, '<td valign="top">I like the structure, could maybe use a little more brightness, but still great.</td>', 'I like the structure, could maybe use a little more brightness, but still great.', '2015-10-26 22:31:25.000000', NULL, 1),
(7412441, 1168576, 112739, '<td valign="top">Nice leading line of the trail. I really like the gradation of colors in the sky.</td>', 'Nice leading line of the trail. I really like the gradation of colors in the sky.', '2015-10-26 22:31:37.000000', NULL, 1),
(7412442, 1168552, 114225, '<td valign="top">I find myself drawn in.</td>', 'I find myself drawn in.', '2015-10-26 22:31:42.000000', NULL, 1),
(7412444, 1168540, 112739, '<td valign="top">Lots of great things to keep the interest. This is a complicated composition, but you managed to keep it all under control very well. bumping.</td>', 'Lots of great things to keep the interest. This is a complicated composition, but you managed to keep it all under control very well. bumping.', '2015-10-26 22:32:55.000000', NULL, 1),
(7412445, 1168622, 112739, '<td valign="top">Very cool rock feature. Very blue!</td>', 'Very cool rock feature. Very blue!', '2015-10-26 22:33:31.000000', NULL, 1),
(7412447, 1168471, 112739, '<td valign="top">I can''t help but want the view out near the end of the concrete piers. The light is gorgeous.</td>', 'I can''t help but want the view out near the end of the concrete piers. The light is gorgeous.', '2015-10-26 22:35:05.000000', NULL, 1),
