(7412449, 1168552, 112739, '<td valign="top">Nice autumn colors. Would like to see more sky though to balance the land and sky out.</td>', 'Nice autumn colors. Would like to see more sky though to balance the land and sky out.', '2015-10-26 22:38:20.000000', NULL, 1),
