(7412506, 1168393, 12611, '<td valign="top">Excellent shot at Letchworth. Spent many a different day there, at all the falls and in the near-woods. Particularly enjoyed the rolling farmland, east aurora to warsaw, dotted with modern windmills. Magical country.</td>', 'Excellent shot at Letchworth. Spent many a different day there, at all the falls and in the near-woods. Particularly enjoyed the rolling farmland, east aurora to warsaw, dotted with modern windmills. Magical country.', '2015-10-27 08:00:34.000000', NULL, 1),
(7412547, 1168280, 163081, '<td valign="top">Gorgeous picture but why the hell you included that ugly fence in your composition. Without that left side I would say ribbon winner. Still give you an 8</td>', 'Gorgeous picture but why the hell you included that ugly fence in your composition. Without that left side I would say ribbon winner. Still give you an 8', '2015-10-27 10:29:47.000000', NULL, 1),
